result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/game2048.py", "content": """"2048 move engine: slide-and-merge for one row + full-board moves."""


def slide_merge_left(row):
    """Slide one row left, merging equal pairs once each. Returns (row, gained)."""
    tiles = [v for v in row if v != 0]
    out = []
    gained = 0
    i = 0
    while i < len(tiles):
        if i + 1 < len(tiles) and tiles[i] == tiles[i + 1]:
            merged = tiles[i] * 2
            out.append(merged)
            gained += merged
            i += 2
        else:
            out.append(tiles[i])
            i += 1
    out += [0] * (len(row) - len(out))
    return out, gained


def _transpose(board):
    return [list(r) for r in zip(*board)]


def move_left(board):
    score = 0
    new = []
    for row in board:
        r, s = slide_merge_left(row)
        new.append(r)
        score += s
    return new, score


def move_right(board):
    score = 0
    new = []
    for row in board:
        rev, s = slide_merge_left(row[::-1])
        new.append(rev[::-1])
        score += s
    return new, score


def move_up(board):
    t = _transpose(board)
    moved, score = move_left(t)
    return _transpose(moved), score


def move_down(board):
    t = _transpose(board)
    moved, score = move_right(t)
    return _transpose(moved), score


MOVES = {"L": move_left, "R": move_right, "U": move_up, "D": move_down}


def can_move(board):
    """True if any move (L/R/U/D) changes the board."""
    for fn in MOVES.values():
        new, _ = fn(board)
        if new != board:
            return True
    # Also true if any cell is empty (a spawn is possible)
    return any(v == 0 for row in board for v in row)


def game_over(board):
    return not can_move(board)
